def accumulate_grads(micro_grads, accum_steps):
    if not micro_grads:
        return []
    acc = [0.0] * len(micro_grads[0])
    for g in micro_grads:
        for i, v in enumerate(g):
            acc[i] += v / accum_steps
    return acc


