def minhash_signature(shingle_set, n_hashes=32):
    sig = []
    for seed in range(n_hashes):
        min_val = None
        for s in shingle_set:
            h = hash(f"{seed}:{s}") % (2**32)
            if min_val is None or h < min_val:
                min_val = h
        sig.append(min_val if min_val is not None else 0)
    return sig


